import{_ as i,c as n,o as t,ag as r}from"./chunks/framework.DfL_BkQ-.js";const g=JSON.parse('{"title":"Fehlerbehebung","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/troubleshooting.md","filePath":"de/guide/troubleshooting.md","lastUpdated":1794112334000}'),a={name:"de/guide/troubleshooting.md"};function l(s,e,o,h,d,u){return t(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="fehlerbehebung" tabindex="-1">Fehlerbehebung <a class="header-anchor" href="#fehlerbehebung" aria-label="Permalink to &quot;Fehlerbehebung&quot;">​</a></h1><h2 id="haufige-probleme" tabindex="-1">Häufige Probleme <a class="header-anchor" href="#haufige-probleme" aria-label="Permalink to &quot;Häufige Probleme&quot;">​</a></h2><h3 id="app-startet-nicht" tabindex="-1">App startet nicht <a class="header-anchor" href="#app-startet-nicht" aria-label="Permalink to &quot;App startet nicht&quot;">​</a></h3><p><strong>Symptome</strong>: Nicasa startet nicht oder stürzt sofort ab</p><p><strong>Lösungen</strong>:</p><ol><li>Stelle sicher, dass du macOS 10.13 oder neuer verwendest</li><li>Prüfe, ob du mindestens 4 GB RAM hast</li><li>Starte deinen Mac neu</li><li>Installiere Nicasa aus dem Mac App Store neu</li><li>Prüfe, ob konkurrierende Apps laufen</li></ol><h3 id="screenshots-funktionieren-nicht" tabindex="-1">Screenshots funktionieren nicht <a class="header-anchor" href="#screenshots-funktionieren-nicht" aria-label="Permalink to &quot;Screenshots funktionieren nicht&quot;">​</a></h3><p><strong>Symptome</strong>: Die Screenshot-Funktion funktioniert nicht</p><p><strong>Lösungen</strong>:</p><ol><li><strong>Berechtigung zur Bildschirmaufnahme erteilen</strong>: <ul><li>Gehe zu Systemeinstellungen &gt; Datenschutz &amp; Sicherheit &gt; Bildschirmaufnahme</li><li>Setze ein Häkchen neben Nicasa</li><li>Starte Nicasa neu</li></ul></li><li>Stelle sicher, dass keine anderen Screenshot-Werkzeuge laufen</li><li>Versuche, deinen Mac neu zu starten</li></ol><h3 id="chrome-erweiterung-funktioniert-nicht" tabindex="-1">Chrome-Erweiterung funktioniert nicht <a class="header-anchor" href="#chrome-erweiterung-funktioniert-nicht" aria-label="Permalink to &quot;Chrome-Erweiterung funktioniert nicht&quot;">​</a></h3><p><strong>Symptome</strong>: Die Erweiterung erscheint nicht oder extrahiert keine Bilder</p><p><strong>Lösungen</strong>:</p><ol><li>Stelle sicher, dass die Erweiterung in Chrome aktiviert ist</li><li>Prüfe, ob du eine kompatible Chrome-Version verwendest</li><li>Lade die Webseite neu</li><li>Installiere die Erweiterung neu</li><li>Leere Browser-Cache und Cookies</li></ol><h3 id="bilder-werden-nicht-geladen" tabindex="-1">Bilder werden nicht geladen <a class="header-anchor" href="#bilder-werden-nicht-geladen" aria-label="Permalink to &quot;Bilder werden nicht geladen&quot;">​</a></h3><p><strong>Symptome</strong>: Miniaturansichten erscheinen nicht oder Bilder lassen sich nicht öffnen</p><p><strong>Lösungen</strong>:</p><ol><li>Prüfe die Dateiberechtigungen der Bilddateien</li><li>Stelle sicher, dass die Bilder nicht beschädigt sind</li><li>Prüfe, ob das Format unterstützt wird (JPEG, PNG, GIF, BMP, TIFF, WebP)</li><li>Öffne den Ordner erneut</li><li>Starte Nicasa neu</li></ol><h3 id="langsame-leistung" tabindex="-1">Langsame Leistung <a class="header-anchor" href="#langsame-leistung" aria-label="Permalink to &quot;Langsame Leistung&quot;">​</a></h3><p><strong>Symptome</strong>: Die App reagiert träge oder Miniaturansichten laden langsam</p><p><strong>Lösungen</strong>:</p><ol><li>Schließe andere speicherintensive Apps</li><li>Stelle ausreichend freien RAM sicher (8 GB empfohlen)</li><li>Verringere die Rastergröße der Miniaturansichten in den Einstellungen</li><li>Leere den App-Cache</li><li>Starte deinen Mac neu</li></ol><h3 id="ki-editor-funktioniert-nicht" tabindex="-1">KI-Editor funktioniert nicht <a class="header-anchor" href="#ki-editor-funktioniert-nicht" aria-label="Permalink to &quot;KI-Editor funktioniert nicht&quot;">​</a></h3><p><strong>Symptome</strong>: KI-Bearbeitungswerkzeuge sind nicht verfügbar oder funktionieren nicht</p><p><strong>Lösungen</strong>:</p><ol><li>Stelle eine stabile Internetverbindung sicher (für einige Funktionen)</li><li>Prüfe, ob dein Mac die Mindestanforderungen erfüllt</li><li>Starte Nicasa neu</li><li>Aktualisiere auf die neueste Version</li><li>Kontaktiere den Support, wenn das Problem bleibt</li></ol><h3 id="berechtigungsprobleme" tabindex="-1">Berechtigungsprobleme <a class="header-anchor" href="#berechtigungsprobleme" aria-label="Permalink to &quot;Berechtigungsprobleme&quot;">​</a></h3><p><strong>Symptome</strong>: Die App fragt nach Berechtigungen oder bestimmte Funktionen funktionieren nicht</p><p><strong>Lösungen</strong>:</p><ol><li><strong>Bildschirmaufnahme</strong>: Systemeinstellungen &gt; Datenschutz &amp; Sicherheit &gt; Bildschirmaufnahme</li><li><strong>Bedienungshilfen</strong>: Systemeinstellungen &gt; Datenschutz &amp; Sicherheit &gt; Bedienungshilfen (für den Overlay-Modus)</li><li><strong>Dateien und Ordner</strong>: Systemeinstellungen &gt; Datenschutz &amp; Sicherheit &gt; Dateien und Ordner</li><li>Starte Nicasa nach dem Erteilen der Berechtigungen neu</li></ol><h3 id="probleme-mit-dem-overlay-modus" tabindex="-1">Probleme mit dem Overlay-Modus <a class="header-anchor" href="#probleme-mit-dem-overlay-modus" aria-label="Permalink to &quot;Probleme mit dem Overlay-Modus&quot;">​</a></h3><p><strong>Symptome</strong>: Der transparente Overlay-Modus funktioniert nicht richtig</p><p><strong>Lösungen</strong>:</p><ol><li>Erteile die Berechtigung für Bedienungshilfen in den Systemeinstellungen</li><li>Stelle sicher, dass keine anderen Overlay-Werkzeuge laufen</li><li>Schalte den Overlay-Modus aus und wieder ein</li><li>Starte Nicasa neu</li></ol><h2 id="fehlermeldungen" tabindex="-1">Fehlermeldungen <a class="header-anchor" href="#fehlermeldungen" aria-label="Permalink to &quot;Fehlermeldungen&quot;">​</a></h2><h3 id="„berechtigung-zur-bildschirmaufnahme-erforderlich" tabindex="-1">„Berechtigung zur Bildschirmaufnahme erforderlich“ <a class="header-anchor" href="#„berechtigung-zur-bildschirmaufnahme-erforderlich" aria-label="Permalink to &quot;„Berechtigung zur Bildschirmaufnahme erforderlich“&quot;">​</a></h3><p><strong>Lösung</strong>: Erteile die Berechtigung zur Bildschirmaufnahme wie oben im Abschnitt „Screenshots funktionieren nicht“ beschrieben.</p><h3 id="„bild-konnte-nicht-geladen-werden" tabindex="-1">„Bild konnte nicht geladen werden“ <a class="header-anchor" href="#„bild-konnte-nicht-geladen-werden" aria-label="Permalink to &quot;„Bild konnte nicht geladen werden“&quot;">​</a></h3><p><strong>Mögliche Ursachen</strong>:</p><ul><li>Die Datei ist beschädigt</li><li>Nicht unterstütztes Format</li><li>Problem mit den Dateiberechtigungen</li><li>Die Datei ist zu groß</li></ul><p><strong>Lösungen</strong>:</p><ol><li>Öffne die Datei mit „Vorschau“, um zu prüfen, ob sie gültig ist</li><li>Konvertiere sie in ein unterstütztes Format</li><li>Prüfe die Dateiberechtigungen</li><li>Stelle sicher, dass die Dateigröße angemessen ist</li></ol><h3 id="„erweiterung-reagiert-nicht" tabindex="-1">„Erweiterung reagiert nicht“ <a class="header-anchor" href="#„erweiterung-reagiert-nicht" aria-label="Permalink to &quot;„Erweiterung reagiert nicht“&quot;">​</a></h3><p><strong>Lösung</strong>: Lade die Webseite neu und versuche es erneut. Wenn das Problem bleibt, installiere die Erweiterung neu.</p><h2 id="hilfe-erhalten" tabindex="-1">Hilfe erhalten <a class="header-anchor" href="#hilfe-erhalten" aria-label="Permalink to &quot;Hilfe erhalten&quot;">​</a></h2><p>Wenn die Probleme weiterhin bestehen:</p><ol><li>Lies diese Anleitung zur Fehlerbehebung</li><li>Besuche unsere <a href="/de/guide/faq.html">FAQ</a></li><li>Reiche ein Issue auf <a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">GitHub</a> ein</li><li>Gib deine macOS-Version, die Nicasa-Version und die genauen Schritte zur Reproduktion an</li></ol><h2 id="systeminformationen" tabindex="-1">Systeminformationen <a class="header-anchor" href="#systeminformationen" aria-label="Permalink to &quot;Systeminformationen&quot;">​</a></h2><p>Wenn du Probleme meldest, gib bitte an:</p><ul><li>macOS-Version (Apple-Menü &gt; Über diesen Mac)</li><li>Nicasa-Version (Nicasa &gt; Über Nicasa)</li><li>Mac-Modell und Chip (Apple Silicon oder Intel)</li><li>Schritte zur Reproduktion des Problems</li><li>Eventuelle Fehlermeldungen</li></ul><p>Das bedeutet normalerweise, dass die Bilddatei verschoben oder gelöscht wurde. Öffne den Ordner erneut oder wähle ein anderes Verzeichnis.</p><h3 id="„nicht-unterstutztes-format" tabindex="-1">„Nicht unterstütztes Format“ <a class="header-anchor" href="#„nicht-unterstutztes-format" aria-label="Permalink to &quot;„Nicht unterstütztes Format“&quot;">​</a></h3><p>Das Bildformat wird nicht erkannt. Prüfe unsere Liste der <a href="/de/guide/usage.html">unterstützten Formate</a> oder konvertiere das Bild in ein kompatibles Format.</p><h3 id="„nicht-genugend-speicher" tabindex="-1">„Nicht genügend Speicher“ <a class="header-anchor" href="#„nicht-genugend-speicher" aria-label="Permalink to &quot;„Nicht genügend Speicher“&quot;">​</a></h3><p>Dein System hat nicht genügend RAM. Schließe andere Apps oder erweitere deinen Arbeitsspeicher.</p><h2 id="erweiterte-fehlerbehebung" tabindex="-1">Erweiterte Fehlerbehebung <a class="header-anchor" href="#erweiterte-fehlerbehebung" aria-label="Permalink to &quot;Erweiterte Fehlerbehebung&quot;">​</a></h2><h3 id="protokolle-anzeigen" tabindex="-1">Protokolle anzeigen <a class="header-anchor" href="#protokolle-anzeigen" aria-label="Permalink to &quot;Protokolle anzeigen&quot;">​</a></h3><p>Zugriff auf die App-Protokolle:</p><ol><li>Gehe zu Hilfe &gt; Protokolle anzeigen</li><li>Oder finde die Protokolle unter: <ul><li>Windows: <code>%APPDATA%\\Nicasa\\logs</code></li><li>macOS: <code>~/Library/Application Support/Nicasa/logs</code></li><li>Linux: <code>~/.config/Nicasa/logs</code></li></ul></li></ol><h3 id="app-zurucksetzen" tabindex="-1">App zurücksetzen <a class="header-anchor" href="#app-zurucksetzen" aria-label="Permalink to &quot;App zurücksetzen&quot;">​</a></h3><p>Um alle Einstellungen auf die Standardwerte zurückzusetzen:</p><ol><li>Schließe Nicasa</li><li>Lösche den Datenordner der App</li><li>Starte Nicasa neu</li></ol><h3 id="kommandozeilenoptionen" tabindex="-1">Kommandozeilenoptionen <a class="header-anchor" href="#kommandozeilenoptionen" aria-label="Permalink to &quot;Kommandozeilenoptionen&quot;">​</a></h3><p>Für fortgeschrittene Nutzer unterstützt Nicasa Kommandozeilenargumente:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nicasa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --verbose</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # Ausführliche Protokollierung aktivieren</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nicasa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reset-settings</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # Alle Einstellungen zurücksetzen</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nicasa</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/folder</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Bestimmten Ordner öffnen</span></span></code></pre></div><h2 id="weitere-hilfe" tabindex="-1">Weitere Hilfe <a class="header-anchor" href="#weitere-hilfe" aria-label="Permalink to &quot;Weitere Hilfe&quot;">​</a></h2><p>Wenn diese Lösungen dein Problem nicht beheben:</p><ol><li>Besuche unsere <a href="/de/guide/faq.html">FAQ</a></li><li>Durchsuche bestehende <a href="https://github.com/nicasa-project/nicasa-support/issues" target="_blank" rel="noreferrer">Issues</a></li><li>Erstelle ein neues Issue mit: <ul><li>Deinem Betriebssystem und der Version</li><li>Der Nicasa-Version</li><li>Den Schritten zur Reproduktion des Problems</li><li>Eventuellen Fehlermeldungen oder Screenshots</li></ul></li></ol>`,68)])])}const p=i(a,[["render",l]]);export{g as __pageData,p as default};
